Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

(* [comment removed for export] *)
Section LE64.
  Variables (ra sp gp tp s0 s1 a0 a1 a2 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : fmem) (S : Z) (bs : list Z) (POST : machine_state -> Prop).
  Hypothesis SRC : bytes_at psegs m S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.

  Notation ST pc x3 x4 x5 x6 x7 y5 y6 y7 :=
    (MS (mkR ra sp gp tp y5 y6 y7 s0 s1 a0 a1 a2 x3 x4 x5 x6 x7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom psegs)).

  Ltac ldb0 p k :=
    let RX := fresh "RX" in
    pose proof (src_rd psegs m S bs (p + k) SRC ltac:(lia)) as RX;
    rewrite ?Z.add_assoc, ?Z.add_0_r in RX;
    zstep; cbv beta; clear RX.

  (* [comment removed for export] *)
  Lemma fast_ld : forall (p x : Z) (x5 x6 x7 y5 y6 y7 : word),
    0 <= p -> p + 8 <= zlen bs -> 0 <= x < 2^31 ->
    (forall (z6 z7 w5 w6 w7 : word),
       evt psegs POST (ST 0x1ce34 (Z_to_bv 64 (Z.land x 7)) (Z_to_bv 64 (S + p)) (Z_to_bv 64 (le64v bs p)) z6 z7 w5 w6 w7)) ->
